const rows = $('Get Meals').all().map(i => i.json)
  .filter(r => r && r.Entry_ID && String(r.Meal_description || '').trim()
    && (r.NOVA === undefined || r.NOVA === null || String(r.NOVA).trim() === ''));
rows.sort((a, b) => Number(b.Entry_ID) - Number(a.Entry_ID));
return rows.slice(0, 8).map(r => ({ json: { Entry_ID: r.Entry_ID, Meal_description: String(r.Meal_description).trim() } }));

const RULES = [
  'NOVA — доминирующая группа переработки по доле калорий блюда: 1 необработанные/минимально обработанные (свежие, сушёные, мороженые овощи, фрукты, крупы, бобовые, орехи, яйца, молоко, мясо, рыба, натуральный йогурт без добавок); 2 кулинарные ингредиенты (растит. и слив. масло, сахар, мёд, соль); 3 обработанные (хлеб, сыр, консервы, соленья, копчёности, свежая выпечка); 4 ультра-обработанные (снеки, газировка и сладкие напитки, колбаса/сосиски, кондитерка и печенье, готовые блюда, фастфуд, сухие завтраки, всё с длинным составом и промышленными добавками). Смешанное блюдо -> группа, дающая больше калорий.',
  'veg_g — овощи БЕЗ картофеля (г). fruit_g — фрукты и ягоды (г), сок НЕ считать. wholegrain_g — цельнозерновые (цельнозерновой хлеб, овсянка, гречка, бурый рис, киноа, перловка); белый хлеб/рис/макароны/манка = 0. legume_nut_g — бобовые + орехи + семена (г). redmeat_g — красное (говядина, свинина, баранина) + переработанное мясо (колбаса, сосиски, бекон, ветчина) (г). ssb_ml — сладкие напитки + фруктовый сок (мл). pufa_g — полиненасыщенные жиры (омега-6 + растительная омега-3 ALA, БЕЗ EPA/DHA), г, оценка.',
  'Если в описании нет количества — оцени по типичной порции. Все числа без единиц измерения.',
  'plants — строка: перечисли ВСЕ разные виды растений в блюде через запятую, включая травы и специи (напр. "овёс, банан, корица"). Пустая строка, если растений нет.',
].join('\n- ');
return $input.all().map(it => ({ json: {
  Entry_ID: it.json.Entry_ID,
  prompt: 'Классифицируй приём пищи для индексов качества рациона. Описание блюда:\n"' + it.json.Meal_description + '"\n\n'
    + 'Верни ТОЛЬКО JSON, без markdown и текста вокруг:\n'
    + '{"NOVA":1,"veg_g":0,"fruit_g":0,"wholegrain_g":0,"legume_nut_g":0,"redmeat_g":0,"ssb_ml":0,"pufa_g":0,"plants":""}\n\n'
    + 'Правила:\n- ' + RULES,
} }));

const outs = $input.all();
const srcs = $('Build Prompts').all();
const num = v => { const n = Number(v); return isFinite(n) ? Math.round(n * 10) / 10 : 0; };
const res = [];
outs.forEach((o, i) => {
  const eid = srcs[i] && srcs[i].json.Entry_ID;
  if (!eid) return;
  let raw = '';
  try { raw = String(o.json.choices[0].message.content || '').trim(); } catch (e) {}
  let j = null;
  try { const s = raw.indexOf('{'), e = raw.lastIndexOf('}'); if (s >= 0 && e > s) j = JSON.parse(raw.slice(s, e + 1)); } catch (err) {}
  if (!j || j.NOVA == null) return;
  const nova = Math.max(1, Math.min(4, Math.round(Number(j.NOVA) || 1)));
  res.push({ json: {
    Entry_ID: eid, NOVA: nova,
    veg_g: num(j.veg_g), fruit_g: num(j.fruit_g), wholegrain_g: num(j.wholegrain_g),
    legume_nut_g: num(j.legume_nut_g), redmeat_g: num(j.redmeat_g), ssb_ml: num(j.ssb_ml),
    'ПНЖ': num(j.pufa_g), plants: String(j.plants || '').trim().slice(0, 300),
  } });
});
return res;

